function slug(value) { return String(value).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60); }

/** Materialise rows into lead-shaped records (no ids assigned here; the importer does that). */
function discoveredLeads() {
  const seen = new Set();
  return ROWS.map(([company, website, sector, province, fye, projectKey, focus, foundationName, parentCompany, tier, note]) => {
    const project = PROJECTS[projectKey];
    const key = slug(company);
    if (seen.has(key)) throw new Error(`duplicate catalogue row: ${company}`);
    seen.add(key);
    return {
      catalogKey: `sa-csi-2026:${key}`,
      company, website: `https://www.${website}/`, sector, province,
      footprint: province === 'Gauteng' && tier === 1 ? 'National' : province,
      financialYearEnd: fye || null, fyeSource: fye ? 'catalogue' : null,
      foundationName, parentCompany,
      projectId: project.id, project: project.name, amount: project.amount[tier - 1],
      partnerPriorities: focus,
      sourceName: 'Corporate website / integrated & CSI reporting (catalogue)', sourceUrl: `https://www.${website}/`,
      notes: `${note} Catalogue entry — confirm current CSI focus, financial year-end and the right public contact (via research + waterfall) before first touch.`,
      tier, catalogue: 'sa-csi-2026'
    };
  });
}

module.exports = { discoveredLeads, PROJECTS, ROWS };
